#include <bits/stdc++.h>
using namespace std;

#define rep(i, n) for(int i = 0; i < n; ++i)

struct path_info{
	int from,to;
	int dist;
};

int main() {
	int n,m,u,v;
	string s;

	cin>>n>>m;

	vector<vector<int> >e(n);
	vector<vector<int> >f(n,vector<int>(2,-1));
	vector<vector<int> >d(n,vector<int>(2,-1));
	queue<path_info>q;

	rep(i,m){
		cin>>u>>v;
		e[u-1].push_back(v-1);
		e[v-1].push_back(u-1);
	}
	cin>>s;
	rep(i,n){
		if(s[i]=='S'){
			f[i][0]=i;
			d[i][0]=0;
			q.push({i,i,0});
		}
	}

	while(!q.empty()){
		path_info tmp=q.front();
		q.pop();
		int u=tmp.from;
		int v=tmp.to;
		int sz=e[v].size();
		rep(i,sz){
			if(f[e[v][i]][0]==-1){
				f[e[v][i]][0]=u;
				d[e[v][i]][0]=tmp.dist+1;
				q.push({u,e[v][i],tmp.dist+1});
			}
			else if((f[e[v][i]][1]==-1)&&(f[e[v][i]][0]!=u)){
				f[e[v][i]][1]=u;
				d[e[v][i]][1]=tmp.dist+1;
				q.push({u,e[v][i],tmp.dist+1});
			}
		}
	}

	rep(i,n){
		if(s[i]=='D')cout<<(d[i][0]+d[i][1])<<endl;
	}

	return 0;
}

import sys
from collections import deque

input = sys.stdin.readline
n, m = map(int, input().split())
g = [[] for _ in range(n)]
for _ in range(m):
    u, v = map(int, input().split())
    u, v = u - 1, v - 1
    g[u].append(v)
    g[v].append(u)
s = input()
ok, ng = [], []
for i in range(n):
    if s[i] == "S":
        ok.append(i)
    else:
        ng.append(i)
INF = 10**9


def f(l):
    d = [INF] * n
    q = deque()
    for x in l:
        d[x] = 0
        q.append(x)
    while q:
        x = q.popleft()
        for i in g[x]:
            if d[i] != INF:
                continue
            d[i] = d[x] + 1
            q.append(i)
    return d


ans = [INF] * len(ng)
for k in range(20):
    c1, c2 = [], []
    for x in ok:
        if (x >> k) & 1:
            c2.append(x)
        else:
            c1.append(x)
    d1, d2 = f(c1), f(c2)
    for i in range(len(ng)):
        x = ng[i]
        ans[i] = min(ans[i], d1[x] + d2[x])
for v in ans:
    print(v)
